CREATE TABLE public.ingestion_items (
    source_url character varying(2048) NOT NULL,
    school_id integer NOT NULL,
    source text NOT NULL,
    directory_source_id bigint,
    status text DEFAULT 'fetch'::text NOT NULL,
    post jsonb,
    attempts smallint DEFAULT 0 NOT NULL,
    claimed_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    carousel_requested_at timestamp with time zone,
    CONSTRAINT ingestion_items_ready_post_check CHECK (((status <> ALL (ARRAY['ready'::text, 'working'::text])) OR (post IS NOT NULL))),
    CONSTRAINT ingestion_items_source_check CHECK ((source = ANY (ARRAY['instagram'::text, 'directory'::text, 'dm'::text]))),
    CONSTRAINT ingestion_items_source_url_check CHECK (((source_url)::text ~ '^https://'::text)),
    CONSTRAINT ingestion_items_status_check CHECK ((status = ANY (ARRAY['fetch'::text, 'ready'::text, 'working'::text, 'done'::text, 'not_event'::text, 'gone'::text, 'failed'::text])))
);


--
-- Name: claim_ingestion_item(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_ingestion_item(p_stage text, p_lease_seconds integer) RETURNS SETOF public.ingestion_items
    LANGUAGE sql
    SET search_path TO ''
    AS $$
    UPDATE public.ingestion_items AS item
    SET status = CASE WHEN p_stage = 'ready' THEN 'working' ELSE 'fetch' END,
        claimed_until = now() + make_interval(secs => p_lease_seconds),
        attempts = item.attempts + 1,
        updated_at = now()
    WHERE item.source_url = (
        SELECT waiting.source_url
        FROM public.ingestion_items AS waiting
        WHERE (
            p_stage = 'fetch'
            AND waiting.status = 'fetch'
            AND (waiting.claimed_until IS NULL OR waiting.claimed_until < now())
        ) OR (
            p_stage = 'ready'
            AND (
                (waiting.status = 'ready'
                    AND (waiting.claimed_until IS NULL OR waiting.claimed_until < now()))
                OR (waiting.status = 'working' AND waiting.claimed_until < now())
            )
        )
        ORDER BY waiting.created_at, waiting.source_url
        FOR UPDATE SKIP LOCKED
        LIMIT 1
    )
    RETURNING item.*;
$$;


