    coordinates double precision[],
    looked_up_at timestamp with time zone,
    claimed_until timestamp with time zone,
    CONSTRAINT map_locations_coordinates_check CHECK (((coordinates IS NULL) OR ((cardinality(coordinates) = 2) AND ((coordinates[1] >= ('-180'::integer)::double precision) AND (coordinates[1] <= (180)::double precision)) AND ((coordinates[2] >= ('-90'::integer)::double precision) AND (coordinates[2] <= (90)::double precision)))))
);


--
-- Name: claim_map_location(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_map_location(p_lease_seconds integer, p_retry_before timestamp with time zone) RETURNS SETOF public.map_locations
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtext('public.claim_map_location'));
    IF EXISTS (SELECT 1 FROM public.map_locations WHERE claimed_until > now()) THEN
        RETURN;
    END IF;
    RETURN QUERY
    UPDATE public.map_locations AS place
    SET claimed_until = now() + make_interval(secs => p_lease_seconds)
    WHERE (place.school_id, place.map_location) = (
        SELECT waiting.school_id, waiting.map_location
        FROM public.map_locations AS waiting
        WHERE waiting.coordinates IS NULL
            AND (waiting.looked_up_at IS NULL OR waiting.looked_up_at < p_retry_before)
        ORDER BY waiting.looked_up_at NULLS FIRST, waiting.school_id, waiting.map_location
        LIMIT 1
    )
    RETURNING place.*;
END;
$$;


--
-- Name: claim_notification_delivery(uuid, text, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_notification_delivery(p_user_id uuid, p_notification_type text, p_target_id text, p_changed_fields jsonb DEFAULT NULL::jsonb, p_stale_before timestamp with time zone DEFAULT (now() - '00:30:00'::interval)) RETURNS TABLE(id uuid, claimed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_id uuid;
BEGIN
    INSERT INTO public.notifications_log (
        user_id,
        notification_type,
        target_id,
        channel,
        status,
        changed_fields,
        attempt_count,
        last_attempt_at
    )
    VALUES (
        p_user_id,
        p_notification_type,
        p_target_id,
        'email',
        'pending',
        p_changed_fields,
        1,
        now()
    )
    ON CONFLICT (user_id, notification_type, target_id, channel)
    DO NOTHING
    RETURNING notifications_log.id INTO v_id;

    IF v_id IS NOT NULL THEN
        RETURN QUERY SELECT v_id, true;
        RETURN;
    END IF;

    UPDATE public.notifications_log AS delivery
    SET
        status = 'pending',
        attempt_count = delivery.attempt_count + 1,
        last_attempt_at = now(),
        failure_category = NULL
    WHERE delivery.user_id = p_user_id
      AND delivery.notification_type = p_notification_type
      AND delivery.target_id = p_target_id
      AND delivery.channel = 'email'
      AND (
          delivery.status = 'failed'
          OR (
              delivery.status = 'pending'
              AND delivery.last_attempt_at < p_stale_before
          )
      )
    RETURNING delivery.id INTO v_id;

    RETURN QUERY
    SELECT
        COALESCE(
            v_id,
            (
                SELECT delivery.id
                FROM public.notifications_log AS delivery
                WHERE delivery.user_id = p_user_id
                  AND delivery.notification_type = p_notification_type
                  AND delivery.target_id = p_target_id
                  AND delivery.channel = 'email'
            )
        ),
        v_id IS NOT NULL;
END;
$$;


--
-- Name: club_listing_counts(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.club_listing_counts(p_club_ids integer[] DEFAULT NULL::integer[]) RETURNS TABLE(club_id integer, listings bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT listed.club_id, count(*)
    FROM (
        SELECT event.club_id FROM public.events AS event WHERE event.club_id IS NOT NULL
        UNION ALL
        SELECT unnest(event.cohost_club_ids) FROM public.events AS event
        UNION ALL
        SELECT position.club_id FROM public.positions AS position
        WHERE position.club_id IS NOT NULL
    ) AS listed
    WHERE p_club_ids IS NULL OR listed.club_id = ANY (p_club_ids)
    GROUP BY listed.club_id;
$$;


