--
-- Name: create_promoter_qr_codes(character varying[], character varying[], uuid, integer, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_promoter_qr_codes(p_ids character varying[], p_names character varying[], p_created_by uuid, p_school_id integer, p_image_url character varying, p_poster_template_id character varying, p_maximum_active_posters integer) RETURNS SETOF public.qr_codes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user public.users%ROWTYPE;
    v_active_count integer;
    v_requested_count integer;
BEGIN
    v_requested_count := COALESCE(cardinality(p_ids), 0);
    IF v_requested_count = 0
       OR cardinality(p_names) <> v_requested_count
       OR p_poster_template_id IS NULL
       OR length(btrim(p_poster_template_id)) = 0
       OR EXISTS (
            SELECT 1
            FROM unnest(p_ids, p_names) AS requested(id, name)
            WHERE requested.id IS NULL
               OR length(btrim(requested.id)) = 0
               OR requested.name IS NULL
               OR length(btrim(requested.name)) = 0
       )
    THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'invalid_promoter_batch';
    END IF;

    SELECT *
    INTO v_user
    FROM public.users
    WHERE id = p_created_by
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'user_not_found';
    END IF;

    IF v_user.payout_email IS NULL
       OR v_user.promoter_tos_accepted_at IS NULL
       OR v_user.promoter_tos_version IS NULL
    THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'promoter_enrollment_required';
    END IF;

    IF p_school_id IS NULL OR v_user.school_id <> p_school_id THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'promoter_school_required';
    END IF;

    SELECT count(*)
    INTO v_active_count
    FROM public.qr_codes
    WHERE created_by = p_created_by
      AND program = 'promoter'
      AND is_active = true;

    IF v_active_count + v_requested_count > p_maximum_active_posters THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'promoter_poster_limit_reached';
    END IF;

    RETURN QUERY
    INSERT INTO public.qr_codes (
        id,
        name,
        description,
        destination_type,
        destination_id,
        filters,
        created_by,
        is_active,
        image_url,
        latitude,
        longitude,
        program,
        poster_template_id,
        school_id
    )
    SELECT
        requested.id,
        requested.name,
        NULL,
        'events-list',
        NULL,
        '{}'::jsonb,
        p_created_by,
        true,
        p_image_url,
        0,
        0,
        'promoter',
        p_poster_template_id,
        p_school_id
    FROM unnest(p_ids, p_names) AS requested(id, name)
    RETURNING *;
END;
$$;


--
-- Name: enforce_event_club_school(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_event_club_school() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_club_school_id integer;
BEGIN
    IF NEW.club_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT club.school_id
    INTO v_club_school_id
    FROM public.clubs AS club
    WHERE club.id = NEW.club_id;

    IF v_club_school_id IS NULL
       OR NEW.school_id <> v_club_school_id
    THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'event school must match its club school';
    END IF;
    RETURN NEW;
END;
$$;


