--
-- Name: freeze_instagram_browser_sources(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_instagram_browser_sources(p_batch_id uuid, p_sources jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_sources jsonb;
BEGIN
    IF p_sources IS NULL OR jsonb_typeof(p_sources) <> 'array' THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'Instagram browser source selection must be an array';
    END IF;

    SELECT browser_delivery_sources
    INTO v_sources
    FROM public.instagram_publish_batches
    WHERE id = p_batch_id AND status = 'published'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'Instagram browser source batch is not published';
    END IF;

    IF v_sources IS NULL THEN
        UPDATE public.instagram_publish_batches
        SET browser_delivery_sources = p_sources
        WHERE id = p_batch_id;
        v_sources := p_sources;
    END IF;

    RETURN v_sources;
END;
$$;


--
-- Name: get_event_click_counts(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_event_click_counts(p_event_ids integer[]) RETURNS TABLE(event_id integer, click_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ui.event_id, COUNT(*)::bigint AS click_count
  FROM public.user_interactions AS ui
  WHERE ui.event_id = ANY(p_event_ids)
    AND ui.interaction_type = 'click'
  GROUP BY ui.event_id;
$$;


--
-- Name: get_event_going_counts(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_event_going_counts(p_event_ids integer[]) RETURNS TABLE(event_id integer, going_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT going.event_id, count(DISTINCT going.user_id)::bigint
    FROM public.user_going_events AS going
    WHERE going.event_id = ANY(p_event_ids)
    GROUP BY going.event_id;
$$;


--
-- Name: get_position_click_counts(integer[]); Type: FUNCTION; Schema: public; Owner: -
