--
-- Name: get_promoter_campus_coverage(integer, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_promoter_campus_coverage(p_school_id integer, p_quiet_cutoff timestamp with time zone, p_coordinate_decimal_places integer) RETURNS TABLE(latitude double precision, longitude double precision, poster_count bigint, recent_poster_count bigint, quiet_poster_count bigint, confirmed_unique_visitors bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH placed_posters AS (
        SELECT
            qr_code.id,
            round(
                qr_code.latitude::numeric,
                p_coordinate_decimal_places
            )::double precision AS cell_latitude,
            round(
                qr_code.longitude::numeric,
                p_coordinate_decimal_places
            )::double precision AS cell_longitude,
            qr_code.latest_scan
        FROM public.qr_codes AS qr_code
        WHERE qr_code.program = 'promoter'
          AND qr_code.is_active = true
          AND qr_code.school_id = p_school_id
          AND NOT (qr_code.latitude = 0 AND qr_code.longitude = 0)
    ),
    cell_visitor_totals AS (
        SELECT
            poster.cell_latitude,
            poster.cell_longitude,
            count(DISTINCT scan.dedupe_hash) AS confirmed_unique_visitors
        FROM public.qr_code_scans AS scan
        JOIN placed_posters AS poster ON poster.id = scan.qr_code_id
        WHERE scan.landing_confirmed_at IS NOT NULL
        GROUP BY poster.cell_latitude, poster.cell_longitude
    )
    SELECT
        poster.cell_latitude,
        poster.cell_longitude,
        count(*),
        count(*) FILTER (WHERE poster.latest_scan >= p_quiet_cutoff),
        count(*) FILTER (
            WHERE poster.latest_scan IS NULL
               OR poster.latest_scan < p_quiet_cutoff
        ),
        COALESCE(visitor.confirmed_unique_visitors, 0)
    FROM placed_posters AS poster
    LEFT JOIN cell_visitor_totals AS visitor
      ON visitor.cell_latitude = poster.cell_latitude
     AND visitor.cell_longitude = poster.cell_longitude
    GROUP BY
        poster.cell_latitude,
        poster.cell_longitude,
        visitor.confirmed_unique_visitors
    ORDER BY poster.cell_latitude, poster.cell_longitude;
$$;


--
-- Name: get_promoter_earnings(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_promoter_earnings(p_user_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS TABLE(qr_code_id character varying, name character varying, is_active boolean, latest_scan timestamp with time zone, latitude double precision, longitude double precision, poster_template_id character varying, image_url character varying, lifetime_unique_scans bigint, period_unique_scans bigint, period_creditable_scans bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH first_visits AS (
        SELECT
            scan.qr_code_id,
            scan.dedupe_hash,
            min(scan.scanned_at) AS first_scanned_at
        FROM public.qr_code_scans AS scan
        JOIN public.qr_codes AS qr_code ON qr_code.id = scan.qr_code_id
        WHERE qr_code.created_by = p_user_id
          AND qr_code.program = 'promoter'
          AND scan.landing_confirmed_at IS NOT NULL
          AND scan.scanned_at < p_period_end
        GROUP BY scan.qr_code_id, scan.dedupe_hash
    ),
    poster_totals AS (
        SELECT
            first_visit.qr_code_id,
            count(*) AS lifetime_unique_scans,
            count(*) FILTER (
                WHERE first_visit.first_scanned_at >= p_period_start
                  AND first_visit.first_scanned_at < p_period_end
            ) AS period_unique_scans,
            min(first_visit.first_scanned_at) AS first_poster_scan
        FROM first_visits AS first_visit
        GROUP BY first_visit.qr_code_id
    )
    SELECT
        qr_code.id,
        qr_code.name,
        qr_code.is_active,
        qr_code.latest_scan,
        qr_code.latitude,
        qr_code.longitude,
        qr_code.poster_template_id,
        qr_code.image_url,
        COALESCE(total.lifetime_unique_scans, 0),
        COALESCE(total.period_unique_scans, 0),
        GREATEST(
            COALESCE(total.period_unique_scans, 0)
            - CASE
                WHEN total.first_poster_scan >= p_period_start
                 AND total.first_poster_scan < p_period_end
                THEN 1
                ELSE 0
              END,
            0
        )
    FROM public.qr_codes AS qr_code
    LEFT JOIN poster_totals AS total ON total.qr_code_id = qr_code.id
    WHERE qr_code.created_by = p_user_id
      AND qr_code.program = 'promoter'
    ORDER BY qr_code.created_at DESC, qr_code.id;
$$;


--
-- Name: going_event_snapshot(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.going_event_snapshot(p_event_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
    SELECT jsonb_build_object(
        'location', event.location,
        'cancelled', event.cancelled,
        'occurrences', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', event_date.id,
                    'event_id', event_date.event_id,
                    'dtstart_utc', event_date.dtstart_utc,
                    'dtend_utc', event_date.dtend_utc,
                    'duration', event_date.duration,
                    'tz', event_date.tz
                )
                ORDER BY event_date.dtstart_utc
            )
            FROM public.event_dates AS event_date
            WHERE event_date.event_id = event.id
        ), '[]'::jsonb),
        -- Captured before deleting a date can cascade away its attendees.
        'going_user_ids', COALESCE((
            SELECT jsonb_agg(DISTINCT going.user_id)
            FROM public.user_going_events AS going
            WHERE going.event_id = event.id
        ), '[]'::jsonb)
    )
    FROM public.events AS event
    WHERE event.id = p_event_id;
$$;


