-- Name: handle_update_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_update_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  new.updated_at = now();
  return new;
END;
$$;


--
-- Name: ingestion_latencies(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingestion_latencies(p_since timestamp with time zone) RETURNS TABLE(school text, added_at timestamp with time zone, latency_seconds double precision)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT school.slug, event.added_at,
        extract(epoch FROM event.added_at - event.source_posted_at)
    FROM public.events AS event
    JOIN public.schools AS school ON school.id = event.school_id
    WHERE event.source_posted_at IS NOT NULL
        AND event.added_at >= p_since
        AND event.added_at >= event.source_posted_at;
$$;


--
-- Name: mark_event_date_school_social_preview_dirty(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_event_date_school_social_preview_dirty() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  affected_event_id bigint;
  affected_school_id integer;
BEGIN
  affected_event_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.event_id ELSE NEW.event_id END;

  SELECT school_id
  INTO affected_school_id
  FROM public.events
  WHERE id = affected_event_id;

  IF affected_school_id IS NOT NULL THEN
    PERFORM public.mark_school_social_preview_dirty(affected_school_id);
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: mark_event_school_social_preview_dirty(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_event_school_social_preview_dirty() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.mark_school_social_preview_dirty(OLD.school_id);
    RETURN OLD;
  END IF;

  PERFORM public.mark_school_social_preview_dirty(NEW.school_id);
  IF TG_OP = 'UPDATE' AND OLD.school_id IS DISTINCT FROM NEW.school_id THEN
    PERFORM public.mark_school_social_preview_dirty(OLD.school_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: poster_payouts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.poster_payouts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    period date NOT NULL,
    payout_email character varying(320) NOT NULL,
    rate_cents integer NOT NULL,
    amount_cents integer NOT NULL,
    scan_count integer NOT NULL,
    status character varying(16) DEFAULT 'pending'::character varying NOT NULL,
    paid_at timestamp with time zone,
    notes text,
    reviewed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_poster_payouts_amount CHECK ((amount_cents = (rate_cents * scan_count))),
    CONSTRAINT chk_poster_payouts_counts CHECK (((amount_cents >= 0) AND (scan_count >= 0))),
    CONSTRAINT chk_poster_payouts_paid_at CHECK (((((status)::text = 'paid'::text) AND (paid_at IS NOT NULL)) OR (((status)::text <> 'paid'::text) AND (paid_at IS NULL)))),
    CONSTRAINT chk_poster_payouts_period_start CHECK ((period = (date_trunc('month'::text, (period)::timestamp without time zone))::date)),
    CONSTRAINT chk_poster_payouts_rate CHECK ((rate_cents > 0)),
    CONSTRAINT chk_poster_payouts_review_notes CHECK ((((status)::text <> ALL (ARRAY[('held'::character varying)::text, ('voided'::character varying)::text])) OR (length(btrim(COALESCE(notes, ''::text))) > 0))),
    CONSTRAINT chk_poster_payouts_status CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('held'::character varying)::text, ('paid'::character varying)::text, ('voided'::character varying)::text])))
);


--
-- Name: mark_poster_payouts_paid(uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_poster_payouts_paid(p_ids uuid[], p_reviewed_by uuid) RETURNS SETOF public.poster_payouts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_requested_count integer;
    v_found_count integer := 0;
    v_locked_status character varying(16);
    v_updated_count integer;
    v_paid_at timestamp with time zone;
BEGIN
    SELECT count(DISTINCT supplied.id)
    INTO v_requested_count
    FROM unnest(COALESCE(p_ids, ARRAY[]::uuid[])) AS supplied(id)
    WHERE supplied.id IS NOT NULL;

    IF v_requested_count = 0 THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'payout_ids_required';
    END IF;

    PERFORM 1
    FROM public.users
    WHERE id = p_reviewed_by
      AND role = 'admin'
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'admin_access_required';
    END IF;

    FOR v_locked_status IN
        SELECT payout.status
        FROM public.poster_payouts AS payout
        WHERE payout.id = ANY(p_ids)
        ORDER BY payout.id
        FOR UPDATE
    LOOP
        v_found_count := v_found_count + 1;
        IF v_locked_status <> 'pending' THEN
            RAISE EXCEPTION USING
                ERRCODE = 'P0001',
                MESSAGE = 'invalid_payout_status_transition';
        END IF;
    END LOOP;

    IF v_found_count <> v_requested_count THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'invalid_payout_status_transition';
    END IF;

    v_paid_at := clock_timestamp();

    RETURN QUERY
    WITH updated_payouts AS (
        UPDATE public.poster_payouts AS payout
        SET
            status = 'paid',
            paid_at = v_paid_at,
            notes = NULL,
            reviewed_by = p_reviewed_by
        WHERE payout.id = ANY(p_ids)
          AND payout.status = 'pending'
        RETURNING payout.*
    ),
    inserted_reviews AS (
        INSERT INTO public.poster_payout_reviews (
            payout_id,
            from_status,
            to_status,
            notes,
            reviewed_by,
            reviewed_at
        )
        SELECT
            payout.id,
            'pending',
            'paid',
            NULL,
            p_reviewed_by,
            v_paid_at
        FROM updated_payouts AS payout
        RETURNING payout_id
    )
    SELECT payout.*
    FROM updated_payouts AS payout
    JOIN inserted_reviews AS review ON review.payout_id = payout.id
    ORDER BY payout.id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    IF v_updated_count <> v_requested_count THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'invalid_payout_status_transition';
    END IF;
END;
$$;


--
-- Name: mark_school_social_preview_dirty(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_school_social_preview_dirty(p_school_id integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  next_revision bigint;
BEGIN
  UPDATE public.schools
  SET social_preview_revision = social_preview_revision + 1
  WHERE id = p_school_id
