--
-- Name: outreach_new_clubs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outreach_new_clubs(p_limit integer) RETURNS TABLE(club_id integer, club_page text, listings bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT club.id, club.club_page::text, listing.listings
    FROM public.club_listing_counts() AS listing
    JOIN public.clubs AS club ON club.id = listing.club_id
    WHERE club.status = 'approved'
        AND club.created_by IS NULL
        AND NOT EXISTS (SELECT 1 FROM public.club_members AS member WHERE member.club_id = club.id)
        AND NOT EXISTS (SELECT 1 FROM public.outreach_leads AS lead WHERE lead.club_id = club.id)
    ORDER BY listing.listings DESC, club.id
    LIMIT p_limit;
$$;


--
-- Name: outreach_unclaimed(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outreach_unclaimed(p_club_ids integer[]) RETURNS SETOF integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT club.id
    FROM public.clubs AS club
    WHERE club.id = ANY (p_club_ids)
        AND club.created_by IS NULL
        AND NOT EXISTS (SELECT 1 FROM public.club_members AS member WHERE member.club_id = club.id);
$$;


--
-- Name: outreach_unscored(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outreach_unscored(p_limit integer) RETURNS TABLE(lead_id uuid, club_id integer, club_name text, ig text, club_page text, email text, listings bigint, page_host_clubs bigint, school_domains text[])
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    WITH pending AS (
        SELECT lead.id, lead.club_id, lead.email
        FROM public.outreach_leads AS lead
        WHERE lead.formality IS NULL
        ORDER BY lead.searched_at, lead.id
        LIMIT p_limit
    ),
    hosts AS (
        SELECT lower(split_part(regexp_replace(club.club_page, '^https?://(www\.)?', ''), '/', 1))
                AS host,
            count(*) AS clubs
        FROM public.clubs AS club
        WHERE club.club_page ~ '^https?://'
        GROUP BY 1
    ),
    counts AS (
        SELECT * FROM public.club_listing_counts((SELECT array_agg(club_id) FROM pending))
    )
    SELECT pending.id, club.id, club.club_name::text, club.ig::text, club.club_page::text,
        pending.email, coalesce(counts.listings, 0), coalesce(hosts.clubs, 0),
        ARRAY(
            SELECT domain.domain::text FROM public.school_email_domains AS domain
            WHERE domain.school_id = club.school_id
        )
    FROM pending
    JOIN public.clubs AS club ON club.id = pending.club_id
    LEFT JOIN counts ON counts.club_id = club.id
    LEFT JOIN hosts ON hosts.host
        = lower(split_part(regexp_replace(club.club_page, '^https?://(www\.)?', ''), '/', 1));
$$;


