CREATE TABLE public.positions (
    id bigint NOT NULL,
    club_id integer NOT NULL,
    school_id integer NOT NULL,
    title character varying(200) NOT NULL,
    description text NOT NULL,
    position_type character varying(32) NOT NULL,
    requirements jsonb DEFAULT '[]'::jsonb NOT NULL,
    commitment character varying(1000),
    compensation character varying(1000),
    location character varying(1000),
    contact_email character varying(320),
    deadline_date date,
    deadline_at timestamp with time zone,
    source_url character varying(1024) NOT NULL,
    source_image_url character varying(1024),
    ingestion_source character varying(32) DEFAULT 'manual'::character varying NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    added_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_paid boolean,
    source_video_url text,
    cohost_club_ids integer[] DEFAULT '{}'::integer[] NOT NULL,
    CONSTRAINT positions_deadline_time_requires_date CHECK (((deadline_at IS NULL) OR (deadline_date IS NOT NULL))),
    CONSTRAINT positions_description_not_blank CHECK ((length(btrim(description)) > 0)),
    CONSTRAINT positions_ingestion_source_valid CHECK (((ingestion_source)::text = ANY (ARRAY[('manual'::character varying)::text, ('instagram_scraper'::character varying)::text, ('directory'::character varying)::text, ('seed'::character varying)::text]))),
    CONSTRAINT positions_requirements_array CHECK ((jsonb_typeof(requirements) = 'array'::text)),
    CONSTRAINT positions_source_url_not_blank CHECK ((length(btrim((source_url)::text)) > 0)),
    CONSTRAINT positions_title_not_blank CHECK ((length(btrim((title)::text)) > 0)),
    CONSTRAINT positions_type_valid CHECK (((position_type)::text = ANY (ARRAY[('executive'::character varying)::text, ('committee'::character varying)::text, ('volunteer'::character varying)::text, ('staff'::character varying)::text, ('internship'::character varying)::text, ('general'::character varying)::text])))
);


