--
-- Name: preserve_instagram_browser_sources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preserve_instagram_browser_sources() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF OLD.browser_delivery_sources IS NOT NULL
       AND NEW.browser_delivery_sources IS DISTINCT FROM OLD.browser_delivery_sources THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'Instagram browser sources are immutable';
    END IF;
    RETURN NEW;
END;
$$;


