--
-- Name: queue_event_map_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_event_map_location() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    INSERT INTO public.map_locations (school_id, map_location)
    VALUES (NEW.school_id, NEW.map_location)
    ON CONFLICT (school_id, map_location) DO NOTHING;
    RETURN NULL;
END;
$$;


--
-- Name: queue_notified_instagram_post(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_notified_instagram_post() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    INSERT INTO public.ingestion_items (source_url, school_id, source)
    SELECT
        'https://www.instagram.com/p/'
            || substring(NEW.source_url FROM '/(?:p|reel|tv)/([A-Za-z0-9_-]+)') || '/',
        notification.school_id,
        'instagram'
    FROM public.instagram_notifications AS notification
    WHERE notification.id = NEW.notification_id
    ON CONFLICT (source_url) DO NOTHING;
    NEW.status := 'succeeded';
    NEW.claim_token := coalesce(NEW.claim_token, gen_random_uuid());
    NEW.succeeded_at := coalesce(NEW.succeeded_at, now());
    NEW.failure_category := NULL;
    RETURN NEW;
END;
$$;


--
-- Name: record_instagram_notification_media(integer, text, text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_instagram_notification_media(p_school_id integer, p_intended_recipient_id text, p_push_id text, p_push_category text, p_cache_ent_id text, p_total_non_mmc_media_count integer, p_media jsonb) RETURNS TABLE(notification_id uuid, newly_inserted_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_notification_id uuid;
    v_materialized_media_count integer;
    v_newly_inserted_count integer;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.schools AS school
        WHERE school.id = p_school_id
          AND school.recipient_id = btrim(p_intended_recipient_id)
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification school recipient mismatch';
    END IF;

    IF p_push_id IS NULL OR length(btrim(p_push_id)) = 0 THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification push id is required';
    END IF;
    IF p_push_category IS NULL OR length(btrim(p_push_category)) = 0 THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification push category is required';
    END IF;
    IF p_total_non_mmc_media_count IS NOT NULL
       AND p_total_non_mmc_media_count < 0
    THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification media count is invalid';
    END IF;
    IF p_media IS NULL OR jsonb_typeof(p_media) <> 'array' THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification media must be an array';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_media) AS item(value)
        WHERE jsonb_typeof(item.value) <> 'object'
           OR COALESCE(jsonb_typeof(item.value -> 'media_id'), '') <> 'string'
           OR COALESCE(jsonb_typeof(item.value -> 'source_url'), '') <> 'string'
           OR btrim(item.value ->> 'media_id') !~ '^[1-9][0-9]{0,31}$'
           OR btrim(item.value ->> 'source_url')
                !~ '^https://(www\.)?instagram\.com/(p|reel|tv)/[A-Za-z0-9_-]+/?$'
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification media item is invalid';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_media) AS item(value)
        GROUP BY btrim(item.value ->> 'media_id')
        HAVING count(DISTINCT btrim(item.value ->> 'source_url')) > 1
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification media URL conflicts with media id';
    END IF;

    INSERT INTO public.instagram_notifications AS stored (
        school_id,
        intended_recipient_id,
        push_id,
        push_category,
        cache_ent_id,
        total_non_mmc_media_count,
        materialized_media_count,
        materialization_status
    )
    VALUES (
        p_school_id,
        btrim(p_intended_recipient_id),
        btrim(p_push_id),
        btrim(p_push_category),
        NULLIF(btrim(p_cache_ent_id), ''),
        p_total_non_mmc_media_count,
        0,
        CASE
            WHEN p_total_non_mmc_media_count IS NOT NULL
             AND p_total_non_mmc_media_count > 0
            THEN 'incomplete'
            ELSE 'complete'
        END
    )
    ON CONFLICT ON CONSTRAINT instagram_notifications_recipient_push_key
    DO UPDATE SET
        cache_ent_id = COALESCE(stored.cache_ent_id, EXCLUDED.cache_ent_id),
        total_non_mmc_media_count = COALESCE(
            stored.total_non_mmc_media_count,
            EXCLUDED.total_non_mmc_media_count
        ),
        materialization_status = CASE
            WHEN COALESCE(
                stored.total_non_mmc_media_count,
                EXCLUDED.total_non_mmc_media_count
            ) IS NOT NULL
             AND stored.materialized_media_count < COALESCE(
                stored.total_non_mmc_media_count,
                EXCLUDED.total_non_mmc_media_count
            )
            THEN 'incomplete'
            ELSE 'complete'
        END,
        last_seen_at = now()
    WHERE stored.school_id = EXCLUDED.school_id
      AND stored.push_category = EXCLUDED.push_category
      AND (
          stored.cache_ent_id IS NULL
          OR EXCLUDED.cache_ent_id IS NULL
          OR stored.cache_ent_id = EXCLUDED.cache_ent_id
      )
      AND (
          stored.total_non_mmc_media_count IS NULL
          OR EXCLUDED.total_non_mmc_media_count IS NULL
          OR stored.total_non_mmc_media_count = EXCLUDED.total_non_mmc_media_count
      )
    RETURNING stored.id INTO v_notification_id;

    IF v_notification_id IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification metadata conflicts with existing push';
    END IF;

    IF EXISTS (
        WITH canonical_media AS (
            SELECT DISTINCT ON (btrim(item.value ->> 'media_id'))
                btrim(item.value ->> 'media_id') AS media_id,
                btrim(item.value ->> 'source_url') AS source_url
            FROM jsonb_array_elements(p_media) WITH ORDINALITY AS item(value, ordinal)
            ORDER BY btrim(item.value ->> 'media_id'), item.ordinal
        )
        SELECT 1
        FROM canonical_media AS incoming
        JOIN public.instagram_notification_media AS stored_media
          ON stored_media.notification_id = v_notification_id
         AND stored_media.media_id = incoming.media_id
        WHERE stored_media.source_url <> incoming.source_url
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'instagram notification media URL conflicts with stored media';
    END IF;

    WITH parsed_media AS (
        SELECT
            btrim(item.value ->> 'media_id') AS media_id,
            btrim(item.value ->> 'source_url') AS source_url,
            item.ordinal
        FROM jsonb_array_elements(p_media) WITH ORDINALITY AS item(value, ordinal)
    ),
    canonical_media AS (
        SELECT DISTINCT ON (parsed.media_id)
            parsed.media_id,
            parsed.source_url,
            parsed.ordinal
        FROM parsed_media AS parsed
        ORDER BY parsed.media_id, parsed.ordinal
    )
    INSERT INTO public.instagram_notification_media (
        notification_id,
        media_id,
        source_url,
        status
    )
    SELECT
        v_notification_id,
        incoming.media_id,
        incoming.source_url,
        'pending'
    FROM canonical_media AS incoming
    ORDER BY incoming.ordinal
    ON CONFLICT ON CONSTRAINT instagram_notification_media_notification_media_key
    DO NOTHING;

    GET DIAGNOSTICS v_newly_inserted_count = ROW_COUNT;

    SELECT count(*)::integer
    INTO v_materialized_media_count
    FROM public.instagram_notification_media AS media
    WHERE media.notification_id = v_notification_id;

    UPDATE public.instagram_notifications AS notification
    SET
        materialized_media_count = v_materialized_media_count,
        materialization_status = CASE
            WHEN notification.total_non_mmc_media_count IS NOT NULL
             AND v_materialized_media_count < notification.total_non_mmc_media_count
            THEN 'incomplete'
            ELSE 'complete'
        END
    WHERE notification.id = v_notification_id;

    RETURN QUERY SELECT v_notification_id, v_newly_inserted_count;
END;
$_$;


--
-- Name: qr_code_scans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.qr_code_scans (
    id uuid NOT NULL,
    qr_code_id character varying(64) NOT NULL,
    scanned_at timestamp with time zone DEFAULT now() NOT NULL,
    dedupe_hash text NOT NULL,
    ip_hash text NOT NULL,
    browser_family character varying(64),
    os_family character varying(64),
    asn bigint,
    country character(2),
    landing_confirmed_at timestamp with time zone,
    risk_score integer DEFAULT 0 NOT NULL,
    risk_flags jsonb DEFAULT '[]'::jsonb NOT NULL,
    risk_evaluated_at timestamp with time zone,
    risk_rules_version character varying(64),
    CONSTRAINT chk_qr_code_scans_country CHECK (((country IS NULL) OR (country ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT chk_qr_code_scans_risk_flags_array CHECK ((jsonb_typeof(risk_flags) = 'array'::text)),
    CONSTRAINT chk_qr_code_scans_risk_score CHECK ((risk_score >= 0))
);


--
-- Name: record_qr_scan(uuid, character varying, text, text, character varying, character varying, bigint, character varying, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_qr_scan(p_scan_id uuid, p_qr_code_id character varying, p_dedupe_hash text, p_ip_hash text, p_browser_family character varying, p_os_family character varying, p_asn bigint, p_country character varying, p_latitude double precision, p_longitude double precision) RETURNS SETOF public.qr_code_scans
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_qr_code public.qr_codes%ROWTYPE;
BEGIN
    SELECT *
    INTO v_qr_code
    FROM public.qr_codes
    WHERE id = p_qr_code_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'qr_code_not_found';
    END IF;

    IF NOT v_qr_code.is_active THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'qr_code_archived';
    END IF;

    IF v_qr_code.program = 'standard' AND v_qr_code.latest_scan IS NULL THEN
        IF p_latitude IS NULL OR p_longitude IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'requires_location';
        END IF;
        UPDATE public.qr_codes
        SET latitude = p_latitude, longitude = p_longitude
        WHERE id = p_qr_code_id;
    ELSIF v_qr_code.program = 'promoter'
       AND v_qr_code.latitude = 0
       AND v_qr_code.longitude = 0
       AND p_latitude IS NOT NULL
       AND p_longitude IS NOT NULL
       AND NOT (p_latitude = 0 AND p_longitude = 0)
    THEN
        UPDATE public.qr_codes
        SET latitude = p_latitude, longitude = p_longitude
        WHERE id = p_qr_code_id;
    END IF;

    RETURN QUERY
    INSERT INTO public.qr_code_scans (
        id,
        qr_code_id,
        dedupe_hash,
        ip_hash,
        browser_family,
        os_family,
        asn,
        country
    )
    VALUES (
        p_scan_id,
        p_qr_code_id,
        p_dedupe_hash,
        p_ip_hash,
        p_browser_family,
        p_os_family,
        p_asn,
        p_country
    )
    RETURNING *;
END;
$$;


--
-- Name: remove_club_cohosts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_club_cohosts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.events SET cohost_club_ids = array_remove(cohost_club_ids, OLD.id)
        WHERE cohost_club_ids @> ARRAY[OLD.id];
    UPDATE public.positions SET cohost_club_ids = array_remove(cohost_club_ids, OLD.id)
        WHERE cohost_club_ids @> ARRAY[OLD.id];
    RETURN OLD;
END;
$$;


--
-- Name: position_submissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.position_submissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    school_id integer NOT NULL,
    position_data jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    rejection_reason text,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    submitted_by_email text,
    CONSTRAINT position_submissions_position_data_check CHECK ((jsonb_typeof(position_data) = 'object'::text)),
    CONSTRAINT position_submissions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


--
-- Name: review_position_submission(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_position_submission(p_id uuid, p_status text, p_reason text, p_reviewer uuid) RETURNS SETOF public.position_submissions
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    submission public.position_submissions;
    payload jsonb;
BEGIN
    SELECT * INTO submission FROM public.position_submissions WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RETURN; END IF;
    IF submission.status = p_status THEN RETURN NEXT submission; RETURN; END IF;
    IF submission.status <> 'pending' OR p_status NOT IN ('approved', 'rejected') THEN
        RAISE EXCEPTION 'Invalid status transition' USING ERRCODE = '23514';
    END IF;
    IF p_status = 'approved' THEN
        payload := submission.position_data;
        INSERT INTO public.positions (
            club_id, school_id, title, description, position_type,
            requirements, commitment, compensation, is_paid, location,
            contact_email, deadline_date, deadline_at, source_url, source_image_url,
            ingestion_source
        ) VALUES (
            (payload->>'club_id')::integer, submission.school_id,
            payload->>'title', payload->>'description', payload->>'position_type',
            coalesce(payload->'requirements', '[]'::jsonb), payload->>'commitment',
            payload->>'compensation', (payload->>'is_paid')::boolean, payload->>'location',
            payload->>'contact_email', (payload->>'deadline_date')::date,
            (payload->>'deadline_at')::timestamptz, payload->>'source_url',
            payload->>'source_image_url', 'manual'
        );
    END IF;
    UPDATE public.position_submissions SET status = p_status,
        rejection_reason = p_reason, reviewed_at = now(), reviewed_by = p_reviewer
        WHERE id = p_id RETURNING * INTO submission;
    RETURN NEXT submission;
END;
$$;


--
-- Name: set_event_map_coordinates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_event_map_coordinates() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    NEW.map_coordinates := (
        SELECT place.coordinates
        FROM public.map_locations AS place
        WHERE place.school_id = NEW.school_id AND place.map_location = NEW.map_location
    );
    RETURN NEW;
END;
$$;


--
-- Name: set_notification_preferences(uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_notification_preferences(p_user_id uuid, p_updates jsonb, p_source text, p_notice_version text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    choice jsonb;
BEGIN
    IF p_source IS NULL OR p_source NOT IN ('settings', 'unsubscribe')
        OR p_notice_version IS NULL OR length(btrim(p_notice_version)) = 0
        OR p_updates IS NULL OR jsonb_typeof(p_updates) <> 'array' THEN
        RAISE EXCEPTION 'Invalid notification preference evidence';
    END IF;
    IF jsonb_array_length(p_updates) NOT BETWEEN 1 AND 32 THEN
        RAISE EXCEPTION 'Invalid notification preference count';
    END IF;

    -- Serialize choices for the same user, including unsubscribe requests.
    PERFORM id FROM public.users WHERE id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Notification preference user not found';
    END IF;

    FOR choice IN SELECT value FROM jsonb_array_elements(p_updates) LOOP
        IF choice->>'notification_type' IS NULL
            OR choice->>'notification_type' NOT IN ('morning_email', 'event_reminder', 'event_change')
            OR jsonb_typeof(choice->'enabled') IS DISTINCT FROM 'boolean'
            OR (p_source = 'unsubscribe' AND (choice->>'enabled')::boolean) THEN
            RAISE EXCEPTION 'Invalid notification preference choice';
        END IF;

        INSERT INTO public.notification_preferences (user_id, notification_type, enabled, updated_at)
        VALUES (p_user_id, choice->>'notification_type', (choice->>'enabled')::boolean, now())
        ON CONFLICT (user_id, notification_type) DO UPDATE
            SET enabled = EXCLUDED.enabled, updated_at = EXCLUDED.updated_at;

        INSERT INTO public.notification_consent_history
            (user_id, notification_type, enabled, source, notice_version)
        VALUES (p_user_id, choice->>'notification_type', (choice->>'enabled')::boolean,
                p_source, p_notice_version);
    END LOOP;
END;
$$;


--
-- Name: set_user_going_occurrences(uuid, integer, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_user_going_occurrences(p_user_id uuid, p_event_id integer, p_occurrence_ids uuid[]) RETURNS TABLE(status text, event_id integer, occurrence_ids uuid[], going_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_occurrence_ids uuid[];
    v_now timestamptz := clock_timestamp();
    v_cancelled boolean;
    v_distinct_event_count integer;
BEGIN
    PERFORM 1
    FROM public.users AS app_user
    WHERE app_user.id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'user_not_found';
    END IF;

    SELECT COALESCE(array_agg(normalized.id ORDER BY normalized.first_position), ARRAY[]::uuid[])
    INTO v_occurrence_ids
    FROM (
        SELECT supplied.id, min(supplied.position) AS first_position
        FROM unnest(COALESCE(p_occurrence_ids, ARRAY[]::uuid[]))
            WITH ORDINALITY AS supplied(id, position)
        WHERE supplied.id IS NOT NULL
        GROUP BY supplied.id
    ) AS normalized;

    SELECT event.cancelled
    INTO v_cancelled
    FROM public.events AS event
    WHERE event.id = p_event_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'event_not_found';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(v_occurrence_ids) AS selected(id)
        LEFT JOIN public.event_dates AS event_date
          ON event_date.id = selected.id
         AND event_date.event_id = p_event_id
        WHERE event_date.id IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'invalid_event_occurrence';
    END IF;

    IF v_cancelled AND cardinality(v_occurrence_ids) > 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'event_cancelled';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.event_dates AS event_date
        WHERE event_date.id = ANY(v_occurrence_ids)
          AND event_date.dtstart_utc < v_now
          AND NOT EXISTS (
              SELECT 1
              FROM public.user_going_events AS existing
              WHERE existing.user_id = p_user_id
                AND existing.event_date_id = event_date.id
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'occurrence_not_selectable';
    END IF;

    IF cardinality(v_occurrence_ids) > 0
       AND NOT EXISTS (
           SELECT 1
           FROM public.user_going_events AS existing
           WHERE existing.user_id = p_user_id
             AND existing.event_id = p_event_id
       )
    THEN
        SELECT count(DISTINCT existing.event_id)
        INTO v_distinct_event_count
        FROM public.user_going_events AS existing
        WHERE existing.user_id = p_user_id;

        IF v_distinct_event_count >= 10000 THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'going_events_cap_reached';
        END IF;
    END IF;

    DELETE FROM public.user_going_events AS existing
    WHERE existing.user_id = p_user_id
      AND existing.event_id = p_event_id;

    INSERT INTO public.user_going_events (
        id,
        user_id,
        event_id,
        event_date_id
    )
    SELECT
        gen_random_uuid(),
        p_user_id,
        p_event_id,
        selected.id
    FROM unnest(v_occurrence_ids) AS selected(id);

    RETURN QUERY
    SELECT
        CASE
            WHEN cardinality(v_occurrence_ids) > 0 THEN 'going'
            ELSE 'not_going'
        END,
        p_event_id,
        v_occurrence_ids,
        (
            SELECT count(DISTINCT existing.user_id)
            FROM public.user_going_events AS existing
            WHERE existing.event_id = p_event_id
        );
END;
$$;


--
-- Name: share_map_location_coordinates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.share_map_location_coordinates() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.events
    SET map_coordinates = NEW.coordinates
    WHERE school_id = NEW.school_id
        AND map_location = NEW.map_location
        AND map_coordinates IS DISTINCT FROM NEW.coordinates;
    RETURN NULL;
END;
$$;


--
-- Name: stamp_position_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_position_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
        NEW.updated_at := now();
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: touch_poster_payout_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_poster_payout_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.updated_at = clock_timestamp();
    RETURN NEW;
END;
$$;


--
-- Name: transition_poster_payout_status(uuid, character varying, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_poster_payout_status(p_payout_id uuid, p_target_status character varying, p_notes text, p_reviewed_by uuid) RETURNS SETOF public.poster_payouts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_current public.poster_payouts%ROWTYPE;
    v_updated public.poster_payouts%ROWTYPE;
    v_notes text := NULLIF(btrim(p_notes), '');
    v_reviewed_at timestamp with time zone;
BEGIN
    PERFORM 1
    FROM public.users
    WHERE id = p_reviewed_by
      AND role = 'admin'
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'admin_access_required';
    END IF;

    SELECT *
    INTO v_current
    FROM public.poster_payouts
    WHERE id = p_payout_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'payout_not_found';
    END IF;

    IF p_target_status IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'invalid_payout_status_transition';
    END IF;

    IF NOT (
        (v_current.status = 'pending' AND p_target_status IN ('held', 'paid'))
        OR
        (v_current.status = 'held' AND p_target_status IN ('pending', 'voided'))
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'invalid_payout_status_transition';
    END IF;

    IF p_target_status IN ('held', 'voided') AND v_notes IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'payout_notes_required';
    END IF;

    v_reviewed_at := clock_timestamp();

    UPDATE public.poster_payouts
    SET
        status = p_target_status,
        paid_at = CASE
            WHEN p_target_status = 'paid' THEN v_reviewed_at
            ELSE NULL
        END,
        notes = CASE
            WHEN p_target_status IN ('held', 'voided') THEN v_notes
            ELSE NULL
        END,
        reviewed_by = p_reviewed_by
    WHERE id = p_payout_id
    RETURNING * INTO v_updated;

    INSERT INTO public.poster_payout_reviews (
        payout_id,
        from_status,
        to_status,
        notes,
        reviewed_by,
        reviewed_at
    )
    VALUES (
        p_payout_id,
        v_current.status,
        p_target_status,
        v_notes,
        p_reviewed_by,
        v_reviewed_at
    );

    RETURN NEXT v_updated;
END;
$$;


--
-- Name: update_event_with_occurrences(integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_event_with_occurrences(p_event_id integer, p_event_patch jsonb, p_occurrences jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_occurrence jsonb;
    v_occurrence_id uuid;
    v_retained_ids uuid[] := ARRAY[]::uuid[];
BEGIN
    PERFORM 1
    FROM public.events AS event
    WHERE event.id = p_event_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'event_not_found';
    END IF;

    UPDATE public.events AS event
    SET
        cohost_club_ids = CASE
            WHEN p_event_patch ? 'cohost_club_ids' THEN
                ARRAY(SELECT jsonb_array_elements_text(p_event_patch->'cohost_club_ids')::integer)
            ELSE event.cohost_club_ids
        END,
        competition = CASE WHEN p_event_patch ? 'competition' THEN (p_event_patch->>'competition')::boolean ELSE event.competition END,
        featured = CASE WHEN p_event_patch ? 'featured' THEN COALESCE((p_event_patch->>'featured')::boolean, false) ELSE event.featured END,
        title = CASE
            WHEN p_event_patch ? 'title' THEN p_event_patch->>'title'
            ELSE event.title
        END,
        description = CASE
            WHEN p_event_patch ? 'description' THEN p_event_patch->>'description'
            ELSE event.description
        END,
        location = CASE
            WHEN p_event_patch ? 'location' THEN p_event_patch->>'location'
            ELSE event.location
        END,
        map_location = CASE
            WHEN p_event_patch ? 'map_location' THEN p_event_patch->>'map_location'
            ELSE event.map_location
        END,
        price = CASE
            WHEN p_event_patch ? 'price' THEN (p_event_patch->>'price')::double precision
            ELSE event.price
        END,
        food = CASE
            WHEN p_event_patch ? 'food'
                THEN NULLIF(p_event_patch->'food', 'null'::jsonb)
            ELSE event.food
        END,
        employers_on_campus = CASE
            WHEN p_event_patch ? 'employers_on_campus' THEN (p_event_patch->>'employers_on_campus')::boolean
            ELSE event.employers_on_campus
        END,
        free_food_on_campus = CASE
            WHEN p_event_patch ? 'free_food_on_campus' THEN (p_event_patch->>'free_food_on_campus')::boolean
            ELSE event.free_food_on_campus
        END,
        sports_game = CASE
            WHEN p_event_patch ? 'sports_game' THEN (p_event_patch->>'sports_game')::boolean
            ELSE event.sports_game
        END,
        campus_season_ids = CASE
            WHEN NOT (p_event_patch ? 'campus_season_ids') THEN event.campus_season_ids
            WHEN p_event_patch->'campus_season_ids' = 'null'::jsonb THEN NULL
            ELSE ARRAY(SELECT jsonb_array_elements_text(p_event_patch->'campus_season_ids'))
        END,
        registration = CASE
            WHEN p_event_patch ? 'registration' THEN (p_event_patch->>'registration')::boolean
            ELSE event.registration
        END,
        source_image_url = CASE
            WHEN p_event_patch ? 'source_image_url' THEN p_event_patch->>'source_image_url'
            ELSE event.source_image_url
        END,
        source_url = CASE
            WHEN p_event_patch ? 'source_url' THEN p_event_patch->>'source_url'
            ELSE event.source_url
        END,
        category = CASE
            WHEN p_event_patch ? 'category' THEN p_event_patch->>'category'
            ELSE event.category
        END,
        club_id = CASE
            WHEN p_event_patch ? 'club_id'
                THEN (p_event_patch->>'club_id')::integer
            ELSE event.club_id
        END,
        club = CASE
            WHEN p_event_patch ? 'club' THEN p_event_patch->>'club'
            ELSE event.club
        END,
        school_id = CASE
            WHEN p_event_patch ? 'school_id'
                THEN (p_event_patch->>'school_id')::integer
            ELSE event.school_id
        END,
        ig_handle = CASE
            WHEN p_event_patch ? 'ig_handle' THEN p_event_patch->>'ig_handle'
            ELSE event.ig_handle
        END,
        cancelled = CASE
            WHEN p_event_patch ? 'cancelled' THEN (p_event_patch->>'cancelled')::boolean
            ELSE event.cancelled
        END
    WHERE event.id = p_event_id;

    IF p_occurrences IS NOT NULL THEN
        IF jsonb_typeof(p_occurrences) <> 'array'
           OR jsonb_array_length(p_occurrences) = 0
        THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'invalid_occurrences';
        END IF;

        IF (
            SELECT count(*)
            FROM jsonb_array_elements(p_occurrences) AS supplied(value)
            WHERE supplied.value ? 'id'
              AND supplied.value->>'id' IS NOT NULL
        ) <> (
            SELECT count(DISTINCT supplied.value->>'id')
            FROM jsonb_array_elements(p_occurrences) AS supplied(value)
            WHERE supplied.value ? 'id'
              AND supplied.value->>'id' IS NOT NULL
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'duplicate_occurrence_id';
        END IF;

        FOR v_occurrence IN
            SELECT supplied.value
            FROM jsonb_array_elements(p_occurrences) AS supplied(value)
        LOOP
            v_occurrence_id := NULLIF(v_occurrence->>'id', '')::uuid;

            IF v_occurrence_id IS NULL THEN
                INSERT INTO public.event_dates (
                    event_id,
                    dtstart_utc,
                    dtend_utc,
                    duration,
                    tz
                )
                VALUES (
                    p_event_id,
                    (v_occurrence->>'dtstart_utc')::timestamptz,
                    (v_occurrence->>'dtend_utc')::timestamptz,
                    v_occurrence->>'duration',
                    v_occurrence->>'tz'
                )
                RETURNING id INTO v_occurrence_id;
            ELSE
                UPDATE public.event_dates AS event_date
                SET
                    dtstart_utc = (v_occurrence->>'dtstart_utc')::timestamptz,
                    dtend_utc = (v_occurrence->>'dtend_utc')::timestamptz,
                    duration = v_occurrence->>'duration',
                    tz = v_occurrence->>'tz'
                WHERE event_date.id = v_occurrence_id
                  AND event_date.event_id = p_event_id;

                IF NOT FOUND THEN
                    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'invalid_occurrence_id';
                END IF;
            END IF;

            v_retained_ids := array_append(v_retained_ids, v_occurrence_id);
        END LOOP;

        DELETE FROM public.event_dates AS event_date
        WHERE event_date.event_id = p_event_id
          AND NOT (event_date.id = ANY(v_retained_ids));
    END IF;
END;
$$;


--
-- Name: instagram_publish_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.instagram_publish_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_key character varying(100) NOT NULL,
    instagram_user_id character varying(64),
    local_date date NOT NULL,
    window_start timestamp with time zone NOT NULL,
    window_end timestamp with time zone NOT NULL,
    status character varying(32) DEFAULT 'generating'::character varying NOT NULL,
    caption text DEFAULT ''::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    error_message text,
    meta_media_id character varying(100),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    published_at timestamp with time zone,
    cover_body text DEFAULT ''::text NOT NULL,
    published_cover_url text,
    school_id integer NOT NULL,
    caption_intro text DEFAULT ''::text NOT NULL,
    batch_kind text DEFAULT 'events'::text NOT NULL,
    sticker_selections jsonb DEFAULT '{}'::jsonb NOT NULL,
    browser_delivery_generation uuid,
    browser_delivery_sources jsonb,
    published_outro_url text,
    permalink text,
    music_status text,
    music_track text,
    music_error text,
    music_attempts integer DEFAULT 0 NOT NULL,
    CONSTRAINT instagram_publish_batches_browser_delivery_sources_check CHECK ((((browser_delivery_sources IS NULL) OR (jsonb_typeof(browser_delivery_sources) = 'array'::text)) AND ((browser_delivery_generation IS NULL) OR (browser_delivery_sources IS NOT NULL)))),
    CONSTRAINT instagram_publish_batches_kind_check CHECK ((batch_kind = ANY (ARRAY['events'::text, 'employers_on_campus'::text]))),
    CONSTRAINT instagram_publish_batches_music_attempts_check CHECK ((music_attempts >= 0)),
    CONSTRAINT instagram_publish_batches_music_status_check CHECK (((music_status IS NULL) OR (music_status = ANY (ARRAY['pending'::text, 'added'::text, 'failed'::text])))),
    CONSTRAINT instagram_publish_batches_status_check CHECK (((status)::text = ANY (ARRAY[('generating'::character varying)::text, ('ready_for_review'::character varying)::text, ('publishing'::character varying)::text, ('published'::character varying)::text, ('empty'::character varying)::text, ('failed'::character varying)::text]))),
    CONSTRAINT instagram_publish_batches_sticker_selections_check CHECK ((jsonb_typeof(sticker_selections) = 'object'::text)),
    CONSTRAINT instagram_publish_batches_version_check CHECK ((version > 0)),
    CONSTRAINT instagram_publish_batches_window_check CHECK ((window_end > window_start))
);


