--
-- Name: update_instagram_publish_batch_draft(uuid, integer, text, text, text, integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_instagram_publish_batch_draft(p_batch_id uuid, p_expected_version integer, p_caption text, p_caption_intro text, p_cover_body text, p_event_ids integer[]) RETURNS SETOF public.instagram_publish_batches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  batch_row public.instagram_publish_batches%rowtype;
  selected_count integer;
begin
  select *
  into batch_row
  from public.instagram_publish_batches
  where id = p_batch_id
  for update;

  if batch_row.id is null then
    raise exception 'instagram publishing batch not found';
  end if;

  if batch_row.version <> p_expected_version then
    raise exception 'instagram publishing batch version conflict';
  end if;

  if batch_row.status not in ('ready_for_review', 'failed') then
    raise exception 'instagram publishing batch is not editable';
  end if;

  selected_count := coalesce(array_length(p_event_ids, 1), 0);
  if selected_count < 1 then
    raise exception 'instagram publishing batch must contain at least one event item';
  end if;

  if (
    select count(distinct event_id)
    from unnest(p_event_ids) as event_id
  ) <> selected_count then
    raise exception 'instagram publishing event ids must be unique';
  end if;

  -- An item carries nothing but its event and its place in the order, so the
  -- saved carousel simply replaces the stored one. Items only ever gain a
  -- published_at once the whole batch publishes, which also makes it
  -- uneditable, so this never discards publish history.
  delete from public.instagram_publish_items where batch_id = p_batch_id;

  insert into public.instagram_publish_items (
    batch_id,
    account_key,
    event_id,
    position
  )
  select
    p_batch_id,
    batch_row.account_key,
    ordered.event_id,
    ordered.ordinality::integer
  from unnest(p_event_ids) with ordinality as ordered(event_id, ordinality);

  return query
  update public.instagram_publish_batches
  set
    caption = p_caption,
    caption_intro = p_caption_intro,
    cover_body = p_cover_body,
    status = 'ready_for_review',
    error_message = null,
    meta_media_id = null,
    version = version + 1,
    updated_at = now()
  where id = p_batch_id
  returning *;
end;
$$;


--
-- Name: update_qr_code_latest_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_qr_code_latest_scan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    UPDATE public.qr_codes
    SET latest_scan = GREATEST(
        COALESCE(latest_scan, '-infinity'::timestamptz),
        NEW.scanned_at
    )
    WHERE id = NEW.qr_code_id;
    RETURN NEW;
END;
$$;


--
-- Name: update_reviewed_position(bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_reviewed_position(p_position_id bigint, p_expected_position jsonb, p_position_patch jsonb) RETURNS SETOF public.positions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
    v_proposed public.positions;
BEGIN
    IF p_position_id IS NULL OR p_position_id <= 0
       OR jsonb_typeof(p_expected_position) IS DISTINCT FROM 'object'
       OR jsonb_typeof(p_expected_position -> 'id') IS DISTINCT FROM 'number'
       OR p_expected_position -> 'id' IS DISTINCT FROM to_jsonb(p_position_id)
       OR jsonb_typeof(p_position_patch) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'Reviewed position update requires a matching baseline and role patch';
    END IF;

    IF p_position_patch = '{}'::jsonb
       OR EXISTS (
           SELECT 1 FROM jsonb_object_keys(p_position_patch) AS field(name)
           WHERE name NOT IN (
               'description', 'position_type', 'requirements', 'commitment',
               'compensation', 'is_paid', 'location', 'contact_email',
               'deadline_date', 'deadline_at'
           )
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'Reviewed position update requires a matching baseline and role patch';
    END IF;

    IF EXISTS (
        SELECT 1 FROM jsonb_each(p_position_patch) AS field(name, value)
        WHERE (name IN ('description', 'position_type') AND jsonb_typeof(value) <> 'string')
           OR (name IN ('commitment', 'compensation', 'location', 'contact_email',
                        'deadline_date', 'deadline_at')
               AND jsonb_typeof(value) NOT IN ('string', 'null'))
           OR (name = 'is_paid' AND jsonb_typeof(value) NOT IN ('boolean', 'null'))
           OR (name = 'requirements' AND jsonb_typeof(value) <> 'array')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'Reviewed position update has invalid role fields';
    END IF;

    BEGIN
        v_proposed := jsonb_populate_record(
            NULL::public.positions, p_expected_position || p_position_patch
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'Reviewed position update has invalid role fields';
    END;

    IF v_proposed.description IS NULL OR length(btrim(v_proposed.description)) NOT BETWEEN 1 AND 4000
       OR v_proposed.position_type IS NULL
       OR v_proposed.position_type NOT IN ('executive', 'committee', 'volunteer', 'staff', 'internship', 'general')
       OR jsonb_typeof(v_proposed.requirements) IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_proposed.requirements) > 12
       OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(v_proposed.requirements) AS requirement(value)
           WHERE jsonb_typeof(value) <> 'string'
              OR length(btrim(value #>> '{}')) NOT BETWEEN 1 AND 300
       )
       OR length(v_proposed.commitment) > 1000 OR length(v_proposed.compensation) > 1000
       OR length(v_proposed.location) > 1000 OR length(v_proposed.contact_email) > 320
       OR (v_proposed.deadline_at IS NOT NULL AND v_proposed.deadline_date IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'Reviewed position update has invalid role fields';
    END IF;

    RETURN QUERY
    UPDATE public.positions AS current_position
    SET description = v_proposed.description,
        position_type = v_proposed.position_type,
        requirements = v_proposed.requirements,
        commitment = v_proposed.commitment,
        compensation = v_proposed.compensation,
        is_paid = v_proposed.is_paid,
        location = v_proposed.location,
        contact_email = v_proposed.contact_email,
        deadline_date = v_proposed.deadline_date,
        deadline_at = v_proposed.deadline_at,
        updated_at = GREATEST(clock_timestamp(), current_position.updated_at + interval '1 microsecond')
    WHERE current_position.id = p_position_id
      AND to_jsonb(current_position) = p_expected_position
      AND EXISTS (
          SELECT 1 FROM jsonb_object_keys(p_position_patch) AS field(name)
          WHERE to_jsonb(current_position) -> name IS DISTINCT FROM to_jsonb(v_proposed) -> name
      )
    RETURNING current_position.*;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'Reviewed position baseline changed or update made no changes';
    END IF;
END;
$$;


--
-- Name: validate_club_cohosts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_club_cohosts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    NEW.cohost_club_ids := ARRAY(
        SELECT DISTINCT club_id FROM unnest(NEW.cohost_club_ids) AS club_id
        WHERE club_id IS DISTINCT FROM NEW.club_id ORDER BY club_id
    );
    -- Lock referenced clubs against concurrent deletion until this write commits.
    PERFORM club.id FROM public.clubs AS club
        WHERE club.id = ANY(NEW.cohost_club_ids) FOR KEY SHARE;
    IF EXISTS (
        SELECT 1 FROM unnest(NEW.cohost_club_ids) AS cohost(id)
        LEFT JOIN public.clubs AS club ON club.id = cohost.id
        WHERE club.id IS NULL OR club.school_id IS DISTINCT FROM NEW.school_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'cohosts must be existing clubs at the same school';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_cohost_school_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_cohost_school_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.school_id IS DISTINCT FROM OLD.school_id AND (
        EXISTS(SELECT 1 FROM public.events WHERE cohost_club_ids @> ARRAY[OLD.id]) OR
        EXISTS(SELECT 1 FROM public.positions WHERE cohost_club_ids @> ARRAY[OLD.id])
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'club is a cohost at its current school';
    END IF;
    RETURN NEW;
END;
$$;


