--
-- Name: schools; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schools (
    id integer NOT NULL,
    slug character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    name character varying(255) NOT NULL,
    timezone character varying(255) NOT NULL,
    recipient_id character varying(32),
    semester_start date,
    semester_end date,
    primary_color character varying(7) NOT NULL,
    secondary_color character varying(7) NOT NULL,
    url_with_semester_dates text NOT NULL,
    social_preview_image_url text,
    social_preview_revision bigint DEFAULT 1 NOT NULL,
    social_preview_rendered_revision bigint DEFAULT 0 NOT NULL,
    social_preview_rendered_at timestamp with time zone,
    faculties text[] DEFAULT '{}'::text[] NOT NULL,
    language text DEFAULT 'en'::text NOT NULL,
    location_examples text[] DEFAULT '{}'::text[] NOT NULL,
    city text,
    poster_logo_url text,
    CONSTRAINT schools_language_check CHECK ((language = ANY (ARRAY['en'::text, 'fr'::text]))),
    CONSTRAINT schools_poster_logo_url_check CHECK (((poster_logo_url IS NULL) OR (poster_logo_url ~ '^https://'::text))),
    CONSTRAINT schools_primary_color_check CHECK (((primary_color)::text ~ '^#[0-9A-Fa-f]{6}$'::text)),
    CONSTRAINT schools_recipient_id_check CHECK (((recipient_id IS NULL) OR ((recipient_id)::text ~ '^[1-9][0-9]{0,31}$'::text))),
    CONSTRAINT schools_secondary_color_check CHECK (((secondary_color)::text ~ '^#[0-9A-Fa-f]{6}$'::text)),
    CONSTRAINT schools_semester_dates_check CHECK ((((semester_start IS NULL) AND (semester_end IS NULL)) OR ((semester_start IS NOT NULL) AND (semester_end IS NOT NULL) AND (semester_start <= semester_end)))),
    CONSTRAINT schools_semester_dates_url_check CHECK ((url_with_semester_dates ~ '^https://'::text)),
    CONSTRAINT schools_slug_check CHECK (((slug)::text ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text)),
    CONSTRAINT schools_social_preview_image_url_check CHECK (((social_preview_image_url IS NULL) OR (social_preview_image_url ~ '^https://'::text))),
    CONSTRAINT schools_social_preview_revision_check CHECK (((social_preview_revision >= 0) AND (social_preview_rendered_revision >= 0) AND (social_preview_rendered_revision <= social_preview_revision)))
);


