    CONSTRAINT chk_users_role_valid CHECK ((role = ANY (ARRAY['user'::text, 'admin'::text])))
);


--
-- Name: admin_list_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_list_entries WITH (security_invoker='true') AS
 SELECT 'events'::text AS resource,
    (e.id)::text AS id,
    s.slug AS school,
    NULL::text AS status,
    (e.category)::text AS category,
    concat_ws(' '::text, e.title, e.club) AS search_text,
    d.starts_at AS sort_at
   FROM ((public.events e
     JOIN ( SELECT event_dates.event_id,
            min(event_dates.dtstart_utc) AS starts_at
           FROM public.event_dates
          GROUP BY event_dates.event_id) d ON ((d.event_id = e.id)))
     JOIN public.schools s ON ((s.id = e.school_id)))
UNION ALL
 SELECT 'reports'::text AS resource,
    (r.id)::text AS id,
    s.slug AS school,
    (r.status)::text AS status,
    NULL::text AS category,
    concat_ws(' '::text, e.title, r.reason, r.event_id) AS search_text,
    r.reported_at AS sort_at
   FROM ((public.reported_events r
     LEFT JOIN public.events e ON ((e.id = r.event_id)))
     LEFT JOIN public.schools s ON ((s.id = e.school_id)))
UNION ALL
 SELECT 'submissions'::text AS resource,
    (es.id)::text AS id,
    s.slug AS school,
    (es.status)::text AS status,
    NULL::text AS category,
    concat_ws(' '::text, (es.event_data ->> 'title'::text), c.club_name, u.email) AS search_text,
    es.submitted_at AS sort_at
   FROM (((public.event_submissions es
     LEFT JOIN public.schools s ON ((s.id = es.school_id)))
     LEFT JOIN public.clubs c ON (((c.id)::text = (es.event_data ->> 'club_id'::text))))
     LEFT JOIN public.users u ON ((u.id = es.user_id)))
UNION ALL
 SELECT 'claims'::text AS resource,
    (cc.id)::text AS id,
    s.slug AS school,
    (cc.status)::text AS status,
    NULL::text AS category,
    concat_ws(' '::text, c.club_name, u.full_name, u.email, cc.executive_role) AS search_text,
    cc.created_at AS sort_at
   FROM (((public.club_claims cc
     LEFT JOIN public.clubs c ON ((c.id = cc.club_id)))
     LEFT JOIN public.schools s ON ((s.id = c.school_id)))
     LEFT JOIN public.users u ON ((u.id = cc.user_id)))
UNION ALL
 SELECT 'clubSubmissions'::text AS resource,
    (c.id)::text AS id,
    s.slug AS school,
    (c.status)::text AS status,
    NULL::text AS category,
    concat_ws(' '::text, c.club_name, u.email) AS search_text,
    NULL::timestamp with time zone AS sort_at
   FROM ((public.clubs c
     LEFT JOIN public.schools s ON ((s.id = c.school_id)))
     LEFT JOIN public.users u ON ((u.id = c.created_by)))
  WHERE c.submitted;


