    CONSTRAINT instagram_notification_media_id_check CHECK (((media_id)::text ~ '^[1-9][0-9]{0,31}$'::text)),
    CONSTRAINT instagram_notification_media_source_url_check CHECK (((source_url)::text ~ '^https://(www\.)?instagram\.com/(p|reel|tv)/[A-Za-z0-9_-]+/?$'::text)),
    CONSTRAINT instagram_notification_media_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('processing'::character varying)::text, ('succeeded'::character varying)::text, ('failed'::character varying)::text]))),
    CONSTRAINT instagram_notification_media_terminal_state_check CHECK (((((status)::text = 'pending'::text) AND (claim_token IS NULL) AND (github_run_id IS NULL) AND (succeeded_at IS NULL) AND (failure_category IS NULL)) OR (((status)::text = 'processing'::text) AND (claim_token IS NOT NULL) AND (succeeded_at IS NULL) AND (failure_category IS NULL)) OR (((status)::text = 'succeeded'::text) AND (claim_token IS NOT NULL) AND (succeeded_at IS NOT NULL) AND (failure_category IS NULL)) OR (((status)::text = 'failed'::text) AND (claim_token IS NOT NULL) AND (succeeded_at IS NULL) AND (failure_category IS NOT NULL) AND ((failure_category)::text ~ '^[a-z0-9][a-z0-9_.:-]{0,99}$'::text))))
);


