--
-- Name: poster_payout_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.poster_payout_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payout_id uuid NOT NULL,
    from_status character varying(16) NOT NULL,
    to_status character varying(16) NOT NULL,
    notes text,
    reviewed_by uuid NOT NULL,
    reviewed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT chk_poster_payout_reviews_notes CHECK (((((to_status)::text <> ALL (ARRAY[('held'::character varying)::text, ('voided'::character varying)::text])) OR (length(btrim(COALESCE(notes, ''::text))) > 0)) AND (length(COALESCE(notes, ''::text)) <= 10000))),
    CONSTRAINT chk_poster_payout_reviews_transition CHECK (((((from_status)::text = 'pending'::text) AND ((to_status)::text = ANY (ARRAY[('held'::character varying)::text, ('paid'::character varying)::text]))) OR (((from_status)::text = 'held'::text) AND ((to_status)::text = ANY (ARRAY[('pending'::character varying)::text, ('voided'::character varying)::text])))))
);


